# «من أهل بيته ﷺ» و«من أصحابه ﷺ» — الدفعة 3 (طلب المستخدم 2026-11-23): python3 data/ahl/batch3.py
# النصوص من نسخ fawazahmed0 (scratchpad/hj/f.py)، والدرجة غير الصحيحين من الدرر؛ فُحصت مقابل البطاقات حتى لا تتكرّر.
import json
SB='صحيح — البخاري'; SM='صحيح — مسلم'; SBM='صحيح — البخاري ومسلم'
A='من أهل بيته ﷺ'; S='من أصحابه ﷺ'
E=[
('B15',A,'أقاربه','ابنة عمّه أم هانئ بنت أبي طالب، أجارت رجلًا يوم فتح مكة، فقال ﷺ: «قد أجرنا من أجرتِ يا أم هانئ»؛ أي: أمّنّا من أمّنتِ.','البخاري 357، ومسلم 336',SBM,'قد أجرنا من أجرت يا أم هانئ',''),
('B16',A,'أقاربه','عمّته صفية بنت عبد المطلب، أم الزبير، ناداها ﷺ: «يا صفية عمّة رسول الله، لا أُغني عنكِ من الله شيئًا»؛ أي: لا ينفع القُربُ منه بلا عمل.','البخاري 2753، ومسلم 206',SBM,'يا صفية عمة رسول الله لا أغني عنك من الله شيئا','قالها حين نزل ﴿وأنذر عشيرتك الأقربين﴾، ونادى معها العباس وفاطمة.'),
('B17',A,'أقاربه','ابن عمّه أبو سفيان بن الحارث، ثبت معه يوم حُنين حين انكشف الناس، آخذًا بلجام بغلته.','البخاري 2874، ومسلم 1776',SBM,'وأبو سفيان بن الحارث آخذ بلجامها','غير أبي سفيان بن حرب والد معاوية. R01 عن ثباته ﷺ يومها، وهذا عن ابن عمّه.'),
('B18',A,'أقاربه','ابن عمّه الفضل بن العباس، أردفه ﷺ خلفه في الحج، من مزدلفة إلى منى.','البخاري 1544، ومسلم 1218',SBM,'ثم أردف الفضل من المزدلفة إلى منى',''),
('B19',A,'أقاربه','أم الفضل، زوجة عمّه العباس، شكّ الناس يوم عرفة: أصائم هو؟ فأرسلت إليه قدح لبن وهو واقف على بعيره، فشربه.','البخاري 1661، ومسلم 1123',SBM,'فأرسلت إليه بقدح لبن وهو واقف على بعيره فشربه',''),
('B20',A,'ربائبه','ربيبه عمر بن أبي سلمة، ابن زوجته أم سلمة، نشأ صغيرًا في حِجره ﷺ، وفي بيته تعلّم آداب الطعام.','البخاري 5376، ومسلم 2022',SBM,'كنت غلاما في حجر رسول الله صلى الله عليه وسلم','الربيب: ابن الزوجة من غيره. «يا غلام سمِّ الله» في بطاقة C26 فلم أكرّرها.'),
('B21',A,'ربائبه','ربيبته زينب بنت أبي سلمة، كان اسمها «بَرّة» فسمّاها ﷺ زينب، وقال: «لا تُزكّوا أنفسكم».','مسلم 2142',SM,'كان اسمي برة فسماني رسول الله صلى الله عليه وسلم زينب … لا تزكوا أنفسكم','بَرّة: من البِرّ، فكره ﷺ أن يمدح الإنسان نفسه باسمه.'),
('S35',S,'أصحابه','أُسيد بن حُضير، قرأ القرآن ليلًا فرأى فوقه مثل الظُّلّة فيها أمثال المصابيح، فقال ﷺ: «تلك الملائكة دنت لصوتك».','البخاري 5018، ومسلم 796',SBM,'تلك الملائكة دنت لصوتك','الظُّلّة: مثل السحابة.'),
('S36',S,'أصحابه','عبد الله بن زيد، رأى الأذان في منامه، فقال ﷺ: «إنها لرؤيا حقّ»، وأمره أن يعلّمه بلالًا لأنه أندى صوتًا.','أبو داود 499، والترمذي 189','حسن صحيح — الترمذي','إنها لرؤيا حق إن شاء الله فقم مع بلال فألق عليه ما رأيت فليؤذن به فإنه أندى صوتا منك',''),
('S37',S,'أصحابه','عبد الله بن عمرو، كان يكتب كل ما يسمعه منه ﷺ، فقال له: «اكتب، فوالذي نفسي بيده ما يخرج منه إلا حق»، وأشار إلى فمه.','أبو داود 3646','صحيح — الألباني والأرناؤوط وأحمد شاكر','اكتب فوالذي نفسي بيده ما يخرج منه إلا حق',''),
('S38',S,'أصحابه','جُليبيب، قُتل في غزوة بعد أن قَتل سبعة، فوقف عليه ﷺ وقال: «هذا مني وأنا منه»، وحمله على ساعديه حتى وُضع في قبره.','مسلم 2472',SM,'قتل سبعة ثم قتلوه هذا مني وأنا منه … فوضعه على ساعديه','في مسلم: «ليس له إلا ساعدا النبي ﷺ» حتى وُضع في قبره.'),
('S39',S,'أصحابه','أبو دُجانة، رفع ﷺ سيفًا يوم أحد وقال: «من يأخذه بحقّه؟» فأخذه أبو دجانة وقاتل به.','مسلم 2470',SM,'من يأخذ مني هذا … فمن يأخذه بحقه … قال أبو دجانة أنا آخذه بحقه',''),
]
out=[dict(id=i,head=h,cat=c,text=t,source=s,grade=g,origin=o,note=nt) for i,h,c,t,s,g,o,nt in E]
for x in out: assert len(x['text'])<=150,(x['id'],len(x['text']))
json.dump({'version':1,'lines':out},open('data/ahl/batch3.json','w'),ensure_ascii=False,indent=1)
print(len(out),'max',max(len(x['text']) for x in out))
